const translations={"staff_page_title":{tr:"Eğitim & Yönetim Kadromuz | Sapmaz Academy",en:"Our Staff & Flight Instructors | Sapmaz Academy"},"nav_about":{tr:"Hakkımızda",en:"About Us"},"nav_staff":{tr:"Kadromuz",en:"Our Staff"},"nav_courses":{tr:"Eğitimler",en:"Courses"},"nav_resources":{tr:"Kaynaklar",en:"Resources"},"nav_news":{tr:"Haberler",en:"News"},"nav_contact":{tr:"İletişim",en:"Contact"},"bc_home":{tr:"Ana Sayfa",en:"Home"},"staff_main_title":{tr:"Eğitim & Yönetim Kadromuz",en:"Our Staff & Flight Instructors"},"staff_main_subtitle":{tr:"Havacılık sektöründe uzun yıllar deneyim kazanmış, uzman eğitmen ve yönetici kadromuz ile tanışın.",en:"Meet our specialist flight instructors and executive administrative board with decades of combined aviation experience."},"tab_educators":{tr:"Eğitmenler",en:"Instructors"},"tab_administrators":{tr:"Yöneticiler",en:"Executives"},"staff_lbl_email":{tr:"E-Posta:",en:"Email:"},"staff_lbl_phone":{tr:"Telefon:",en:"Phone:"},"pagination_prev":{tr:"Önceki",en:"Previous"},"pagination_next":{tr:"Sonraki",en:"Next"},"no_staff_results":{tr:"Bu kategoride kayıtlı personel bulunamadı.",en:"No staff members found in this category."},"footer_title_about":{tr:"Sapmaz Havacılık",en:"Sapmaz Aviation"},"footer_desc":{tr:"Havacılık sektörüne yön veren Sapmaz Grubu, pilotluk ve drone teknolojilerindeki 20 yılı aşkın tecrübesiyle profesyoneller yetiştirir.",en:"Leading the aviation industry, Sapmaz Group trains professionals with over 20 years of experience in flight training & drone technology."},"footer_title_links":{tr:"Kurumsal Bilgiler",en:"Information Hub"},"footer_link_accreditations":{tr:"Sertifikalar ve Yetkilerimiz",en:"Accreditations & Certificates"},"footer_link_careers":{tr:"Havacılık Kariyer Rehberi",en:"Aviation Careers Guide"},"footer_link_privacy":{tr:"Gizlilik ve KVKK Politikası",en:"Privacy & GDPR Data Policy"},"footer_link_terms":{tr:"Kullanım Şartları",en:"Terms & Conditions"},"footer_title_contact":{tr:"İletişim Bilgileri",en:"Contact Information"},"contact_address_label":{tr:"Merkez Ofis",en:"Headquarters"},"contact_address":{tr:"Sapmaz Plaza, Kat: 4, Havacılık Cd. No:12, Kadıköy / İstanbul",en:"Sapmaz Plaza, Floor: 4, Havacilik St. No:12, Kadikoy / Istanbul"},"contact_email_label":{tr:"E-Posta",en:"Email Address"},"contact_phone_label":{tr:"Müşteri İlişkileri",en:"Customer Relations"},"footer_rights":{tr:"Tüm Hakları Saklıdır.",en:"All Rights Reserved."},"footer_design":{tr:"Havacılık Eğitim Sistemleri Tasarımı",en:"Aviation Training Systems Design"}};const staffData=[{id:1,name:"Eren Burçin Budak",category:"educator",roleTR:"Eğitim Müdürü, İHA2 Pilotu, Eğitmen",roleEN:"Training Director, UAV2 Pilot & Instructor",email:"eren.budak@sapmazacademy.com",phone:"+90 (216) 555 4282",imgUrl:"../assets/images/staff/eren_budak.png"},{id:2,name:"Mehmet Efe Gökgöz",category:"educator",roleTR:"İHA2 Pilotu",roleEN:"UAV2 Pilot & Instructor",email:"efe.gokgoz@sapmazacademy.com",phone:"+90 (216) 555 4282",imgUrl:"../assets/images/staff/efe_gokgoz.jpeg"},{id:3,name:"Sude Güray",category:"educator",roleTR:"Eğitmen",roleEN:"Flight Instructor",email:"sude.guray@sapmazacademy.com",phone:"+90 (216) 555 4282",imgUrl:"../assets/images/staff/sude_guray.jpeg"},{id:4,name:"Eren Burçin Budak",category:"administrator",roleTR:"Eğitim Müdürü, İHA2 Pilotu, Eğitmen",roleEN:"Training Director, UAV2 Pilot & Instructor",email:"eren.budak@sapmazacademy.com",phone:"+90 (216) 555 4282",imgUrl:"../assets/images/staff/eren_budak.png"}];document.addEventListener("DOMContentLoaded",()=>{setupMobileMenu();setupTheme();setupLanguage();renderStaff()});function setupMobileMenu(){const hamburger=document.getElementById("hamburger");const navMenu=document.getElementById("navMenu");const navLinks=document.querySelectorAll(".nav-link");if(hamburger&&navMenu){hamburger.addEventListener("click",()=>{hamburger.classList.toggle("open");navMenu.classList.toggle("open")});navLinks.forEach(link=>{link.addEventListener("click",()=>{hamburger.classList.remove("open");navMenu.classList.remove("open")})})}}function setupTheme(){document.body.classList.add("light-mode")}function setupLanguage(){const langSelect=document.getElementById("langSelect");let currentLang=localStorage.getItem("language")||"tr";if(langSelect){langSelect.value=currentLang;langSelect.addEventListener("change",(e)=>{const selectedLang=e.target.value;localStorage.setItem("language",selectedLang);updatePageLanguage(selectedLang);document.documentElement.lang=selectedLang;renderStaff()})}updatePageLanguage(currentLang)}function updatePageLanguage(lang){const translatableElements=document.querySelectorAll("[data-i18n]");translatableElements.forEach(element=>{const key=element.getAttribute("data-i18n");if(translations[key]&&translations[key][lang]){element.textContent=translations[key][lang]}})}function renderStaff(){const gridContainer=document.getElementById("staffGrid");const paginationContainer=document.getElementById("staffPagination");if(!gridContainer)return;const lang=localStorage.getItem("language")||"tr";const educators=staffData.filter(item=>item.category==="educator");const administrators=staffData.filter(item=>item.category==="administrator");if(staffData.length===0){const noResultsText=translations["no_staff_results"][lang];gridContainer.innerHTML=`<div class="news-no-results">${noResultsText}</div>`;return}let htmlContent="";if(educators.length>0){const educatorsTitle=translations["tab_educators"][lang];htmlContent+=`<h2 class="staff-category-title">${educatorsTitle}</h2><div class="staff-grid">`;educators.forEach(item=>{const role=lang==="tr"?item.roleTR:item.roleEN;htmlContent+=`<div class="staff-card"><div class="staff-card-img-wrapper"><img src="${item.imgUrl}" alt="${item.name}" class="staff-card-img" onerror="this.onerror=null;" /></div><div class="staff-card-info"><h3 class="staff-card-name">${item.name}</h3><span class="staff-card-role">${role}</span></div></div>`});htmlContent+=`</div>`}if(administrators.length>0){const administratorsTitle=translations["tab_administrators"][lang];htmlContent+=`<h2 class="staff-category-title">${administratorsTitle}</h2><div class="staff-grid">`;administrators.forEach(item=>{const role=lang==="tr"?item.roleTR:item.roleEN;htmlContent+=`<div class="staff-card"><div class="staff-card-img-wrapper"><img src="${item.imgUrl}" alt="${item.name}" class="staff-card-img" onerror="this.onerror=null;" /></div><div class="staff-card-info"><h3 class="staff-card-name">${item.name}</h3><span class="staff-card-role">${role}</span></div></div>`});htmlContent+=`</div>`}gridContainer.innerHTML=htmlContent;if(paginationContainer){paginationContainer.innerHTML=""}}